// Signs the request to Convex with N8N_TO_CONVEX_SECRET (a different secret
// from the one Convex uses towards n8n).
const crypto = require('crypto');
const secret = $env.N8N_TO_CONVEX_SECRET;
if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set');

const date = new Date().toISOString().slice(0, 10); // UTC, same as Convex
const body = JSON.stringify({ date });
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
return [{ json: { body, timestamp, signature } }];

// One item per overdue loan. No items → the rest of the workflow is skipped.
const { date, loans } = $input.first().json;
console.log(JSON.stringify({ event: 'overdue_scan', date, count: loans.length }));
return loans.map((loan) => ({ json: loan }));

const appUrl = $env.LENDLOOP_APP_URL || 'http://localhost:3000';
return $input.all().map(({ json: l }) => {
  const first = (l.borrower.name || '').split(/\s+/)[0] || 'there';
  const days = l.daysOverdue === 1 ? '1 day' : l.daysOverdue + ' days';
  return { json: {
    loanId: l.loanId,
    idempotencyKey: l.idempotencyKey,
    to: l.borrower.email,
    subject: '[LendLoop] Reminder: please return the ' + l.toolName,
    text: 'Hi ' + first + ',\n\nThe ' + l.toolName + ' you borrowed from ' + l.ownerFirstName +
      ' was due back on ' + l.endDate + ' (' + days + ' ago). Please return it as soon as you can.\n\n' +
      'Your loans: ' + appUrl + '/my/requests\n\n— LendLoop',
  } };
});

// Writes the outcome of each reminder back to Convex. The idempotency key
// makes retries and re-runs safe: Convex records each (loan, day) once.
const crypto = require('crypto');
const secret = $env.N8N_TO_CONVEX_SECRET;
if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set');

return $input.all().map((item, i) => {
  const reminder = $('Compose reminder').itemMatching(i).json;
  const failed = Boolean(item.json.error);
  const ack = {
    loanId: reminder.loanId,
    idempotencyKey: reminder.idempotencyKey,
    status: failed ? 'failed' : 'sent',
    ...(failed ? { error: String(item.json.error.message || item.json.error).slice(0, 300) } : {}),
  };
  const body = JSON.stringify(ack);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
  console.log(JSON.stringify({ event: 'reminder_result', key: ack.idempotencyKey, status: ack.status }));
  return { json: { body, timestamp, signature } };
});
